423→// ListTemporaryCheckpoints lists all checkpoint commits on a shadow branch.
424→// This returns individual commits (rewind points), not just branch info.
425→// The sessionID filter, if provided, limits results to commits from that session.
426→// worktreeID should be empty for main worktree or the internal git worktree name for linked worktrees.
427→func (s *GitStore) ListTemporaryCheckpoints(ctx context.Context, baseCommit, worktreeID, sessionID string, limit int) ([]TemporaryCheckpointInfo, error) {
428→	shadowBranchName := ShadowBranchNameForCommit(baseCommit, worktreeID)
429→	return s.listCheckpointsForBranch(ctx, shadowBranchName, sessionID, limit)
430→}
