439→// listCheckpointsForBranch lists checkpoint commits for a specific shadow branch name.
440→// This is an internal helper used by ListTemporaryCheckpoints, ListCheckpointsForBranch, and ListAllTemporaryCheckpoints.
441→func (s *GitStore) listCheckpointsForBranch(ctx context.Context, shadowBranchName, sessionID string, limit int) ([]TemporaryCheckpointInfo, error) {
442→	if err := ctx.Err(); err != nil {
443→		return nil, err //nolint:wrapcheck // Propagating context cancellation
444→	}
445→
446→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
447→
448→	ref, err := s.repo.Reference(refName, true)
449→	if err != nil {
450→		return nil, nil //nolint:nilerr // No shadow branch is expected case
451→	}
452→
453→	iter, err := s.repo.Log(&git.LogOptions{From: ref.Hash()})
454→	if err != nil {
455→		return nil, fmt.Errorf("failed to get commit log: %w", err)
456→	}
457→
458→	var results []TemporaryCheckpointInfo
459→	count := 0
460→
461→	err = iter.ForEach(func(c *object.Commit) error {
462→		if err := ctx.Err(); err != nil {
463→			return err //nolint:wrapcheck // Propagating context cancellation
464→		}
465→		if count >= limit*5 { // Scan more to allow for session filtering
466→			return errStop
467→		}
468→		count++
469→
470→		// Verify commit belongs to target session via Entire-Session trailer
471→		commitSessionID, hasTrailer := trailers.ParseSession(c.Message)
472→		if !hasTrailer {
473→			return nil // Skip commits without session trailer
474→		}
475→		if sessionID != "" && commitSessionID != sessionID {
476→			return nil // Skip commits from other sessions
477→		}
478→
479→		// Get first line of message
480→		message := c.Message
481→		if idx := strings.Index(message, "\n"); idx > 0 {
482→			message = message[:idx]
483→		}
484→
485→		info := TemporaryCheckpointInfo{

