171→// Session helper methods - work on AgentSession with Claude's native JSONL data
172→
173→// GetLastUserPrompt extracts the last user prompt from the session.
174→// Requires NativeData to be populated (call ReadSession first).
175→func (c *ClaudeCodeAgent) GetLastUserPrompt(session *agent.AgentSession) string {
176→	if session == nil || len(session.NativeData) == 0 {
177→		return ""
178→	}
179→
180→	lines, err := transcript.ParseFromBytes(session.NativeData)
181→	if err != nil {
182→		return ""
183→	}
184→
185→	return ExtractLastUserPrompt(lines)
186→}
