275→// writeStandardCheckpointEntries writes session files to numbered subdirectories and
276→// maintains a CheckpointSummary at the root level with aggregated statistics.
277→//
278→// Structure:
279→//
280→//	basePath/
281→//	├── metadata.json         # CheckpointSummary (aggregated stats)
282→//	├── 1/                    # First session
283→//	│   ├── metadata.json     # CommittedMetadata (session-specific, includes initial_attribution)
284→//	│   ├── full.jsonl
285→//	│   ├── prompt.txt
286→//	│   ├── context.md
287→//	│   └── content_hash.txt
288→//	├── 2/                    # Second session
289→//	└── ...
290→func (s *GitStore) writeStandardCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
291→	// Read existing summary to get current session count
292→	var existingSummary *CheckpointSummary
293→	metadataPath := basePath + paths.MetadataFileName
294→	if entry, exists := entries[metadataPath]; exists {
295→		existing, err := s.readSummaryFromBlob(entry.Hash)
296→		if err == nil {
297→			existingSummary = existing
298→		}
299→	}
300→
301→	// Determine session index: reuse existing slot if session ID matches, otherwise append
302→	sessionIndex := s.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
303→
304→	// Write session files to numbered subdirectory
305→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
306→	sessionFilePaths, err := s.writeSessionToSubdirectory(ctx, opts, sessionPath, entries)
307→	if err != nil {
308→		return err
309→	}
310→
311→	// Copy additional metadata files from directory if specified (to session subdirectory)
312→	if opts.MetadataDir != "" {
313→		if err := s.copyMetadataDir(opts.MetadataDir, sessionPath, entries); err != nil {
314→			return fmt.Errorf("failed to copy metadata directory: %w", err)
315→		}
316→	}
317→
318→	// Build the sessions array
319→	var sessions []SessionFilePaths
320→	if existingSummary != nil {
321→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
322→		copy(sessions, existingSummary.Sessions)
323→	} else {
324→		sessions = make([]SessionFilePaths, 1)
325→	}
326→	sessions[sessionIndex] = sessionFilePaths
327→
328→	// Update root metadata.json with CheckpointSummary
329→	return s.writeCheckpointSummary(opts, basePath, entries, sessions)
330→}
