457→// findSessionIndex returns the index of an existing session with the given ID,
458→// or the next available index if not found. This prevents duplicate session entries.
459→func (s *GitStore) findSessionIndex(ctx context.Context, basePath string, existingSummary *CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
460→	if existingSummary == nil {
461→		return 0
462→	}
463→	for i := range len(existingSummary.Sessions) {
464→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
465→		if entry, exists := entries[path]; exists {
466→			meta, err := s.readMetadataFromBlob(entry.Hash)
467→			if err != nil {
468→				logging.Warn(ctx, "failed to read session metadata during dedup check",
469→					slog.Int("session_index", i),
470→					slog.String("session_id", sessionID),
471→					slog.String("error", err.Error()),
472→				)
473→				continue
474→			}
475→			if meta.SessionID == sessionID {
476→				return i
477→			}
478→		}
479→	}
480→	return len(existingSummary.Sessions)
481→}
