483→// reaggregateFromEntries reads all session metadata from the entries map and
484→// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
485→func (s *GitStore) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
486→	var totalCount int
487→	var allFiles []string
488→	var totalTokens *agent.TokenUsage
489→
490→	for i := range sessionCount {
491→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
492→		entry, exists := entries[path]
493→		if !exists {
494→			return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
495→		}
496→		meta, err := s.readMetadataFromBlob(entry.Hash)
497→		if err != nil {
498→			return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
499→		}
500→		totalCount += meta.CheckpointsCount
501→		allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
502→		totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
503→	}
504→
505→	return totalCount, allFiles, totalTokens, nil
506→}
