508→// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
509→func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
510→	blob, err := repo.BlobObject(hash)
511→	if err != nil {
512→		return nil, fmt.Errorf("failed to get blob: %w", err)
513→	}
514→
515→	reader, err := blob.Reader()
516→	if err != nil {
517→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
518→	}
519→	defer reader.Close()
520→
521→	var result T
522→	if err := json.NewDecoder(reader).Decode(&result); err != nil {
523→		return nil, fmt.Errorf("failed to decode: %w", err)
524→	}
525→
526→	return &result, nil
527→}
