536→func aggregateTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
537→	if a == nil && b == nil {
538→		return nil
539→	}
540→	result := &agent.TokenUsage{}
541→	if a != nil {
542→		result.InputTokens = a.InputTokens
543→		result.CacheCreationTokens = a.CacheCreationTokens
544→		result.CacheReadTokens = a.CacheReadTokens
545→		result.OutputTokens = a.OutputTokens
546→		result.APICallCount = a.APICallCount
547→	}
548→	if b != nil {
549→		result.InputTokens += b.InputTokens
550→		result.CacheCreationTokens += b.CacheCreationTokens
551→		result.CacheReadTokens += b.CacheReadTokens
552→		result.OutputTokens += b.OutputTokens
553→		result.APICallCount += b.APICallCount
554→	}
555→	return result
556→}
