312→			incData, err = redact.JSONLBytes(opts.IncrementalData)
313→			if err != nil {
314→				return plumbing.ZeroHash, fmt.Errorf("failed to redact incremental checkpoint: %w", err)
315→			}
316→		}
317→		incrementalCheckpoint := struct {
318→			Type      string          `json:"type"`
319→			ToolUseID string          `json:"tool_use_id"`
320→			Timestamp time.Time       `json:"timestamp"`
321→			Data      json.RawMessage `json:"data"`
322→		}{
323→			Type:      opts.IncrementalType,
324→			ToolUseID: opts.ToolUseID,
325→			Timestamp: time.Now().UTC(),
326→			Data:      incData,
327→		}
328→		cpData, err := jsonutil.MarshalIndentWithNewline(incrementalCheckpoint, "", "  ")
329→		if err != nil {
330→			return plumbing.ZeroHash, fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
331→		}
332→
333→		cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
334→		if err != nil {
335→			return plumbing.ZeroHash, fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
336→		}
337→		cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
338→		cpPath := taskMetadataDir + "/checkpoints/" + cpFilename
339→		changes = append(changes, TreeChange{
340→			Path:  cpPath,
341→			Entry: &object.TreeEntry{Mode: filemode.Regular, Hash: cpBlobHash},
342→		})
343→	} else {
344→		// Final checkpoint: add transcripts and checkpoint.json
345→
346→		// Add session transcript (with chunking support for large transcripts)
347→		if opts.TranscriptPath != "" {
348→			if transcriptContent, readErr := os.ReadFile(opts.TranscriptPath); readErr == nil {
349→				agentType := agent.DetectAgentTypeFromContent(transcriptContent)
350→
351→				// Chunk if necessary
352→				chunks, chunkErr := agent.ChunkTranscript(ctx, transcriptContent, agentType)
353→				if chunkErr != nil {
354→					logging.Warn(ctx, "failed to chunk transcript, checkpoint will be saved without transcript",
355→						slog.String("error", chunkErr.Error()),

356→						slog.String("session_id", opts.SessionID),
357→					)
358→				} else {
359→					for i, chunk := range chunks {
360→						chunkPath := sessionMetadataDir + "/" + agent.ChunkFileName(paths.TranscriptFileName, i)
361→						blobHash, blobErr := CreateBlobFromContent(s.repo, chunk)
362→						if blobErr != nil {
363→							logging.Warn(ctx, "failed to create blob for transcript chunk",
364→								slog.String("error", blobErr.Error()),
365→								slog.String("session_id", opts.SessionID),
366→								slog.Int("chunk_index", i),
367→							)
368→							continue
369→						}
370→						changes = append(changes, TreeChange{
371→							Path:  chunkPath,
372→							Entry: &object.TreeEntry{Mode: filemode.Regular, Hash: blobHash},
373→						})
374→					}
375→				}
376→			}
377→		}
378→
379→		// Add subagent transcript if available
380→		if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
381→			if agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath); readErr == nil {
382→				redacted, jsonlErr := redact.JSONLBytes(agentContent)
383→				if jsonlErr != nil {
384→					logging.Warn(ctx, "subagent transcript is not valid JSONL, falling back to plain redaction",
385→						slog.String("path", opts.SubagentTranscriptPath),
386→						slog.String("error", jsonlErr.Error()),
387→					)
388→					redacted = redact.Bytes(agentContent)
389→				}
390→				agentContent = redacted
391→				if blobHash, blobErr := CreateBlobFromContent(s.repo, agentContent); blobErr == nil {
392→					agentPath := taskMetadataDir + "/agent-" + opts.AgentID + ".jsonl"
393→					changes = append(changes, TreeChange{
394→						Path:  agentPath,
395→						Entry: &object.TreeEntry{Mode: filemode.Regular, Hash: blobHash},
396→					})
397→				}
398→			}
399→		}
400→
401→		// Add checkpoint.json
402→		checkpointJSON := fmt.Sprintf(`{
403→  "session_id": %q,
404→  "tool_use_id": %q,
405→  "checkpoint_uuid": %q,
406→  "agent_id": %q
407→}`, opts.SessionID, opts.ToolUseID, opts.CheckpointUUID, opts.AgentID)
408→
409→		blobHash, err := CreateBlobFromContent(s.repo, []byte(checkpointJSON))
410→		if err != nil {
411→			return plumbing.ZeroHash, fmt.Errorf("failed to create checkpoint blob: %w", err)
412→		}
413→		checkpointPath := taskMetadataDir + "/checkpoint.json"
414→		changes = append(changes, TreeChange{
415→			Path:  checkpointPath,
416→			Entry: &object.TreeEntry{Mode: filemode.Regular, Hash: blobHash},
417→		})
418→	}
419→
420→	return ApplyTreeChanges(s.repo, baseTreeHash, changes)
421→}
