421→// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
422→// sessions is the complete sessions array (already built by the caller).
423→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths) error {
424→	checkpointsCount, filesTouched, tokenUsage, err :=
425→		s.reaggregateFromEntries(basePath, len(sessions), entries)
