package checkpoint

import (
	"encoding/json"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestCommittedMetadata_SubagentsField(t *testing.T) {
	t.Parallel()

	t.Run("round_trip_marshal_unmarshal", func(t *testing.T) {
		t.Parallel()

		original := CommittedMetadata{
			CheckpointID: "abc123def456",
			SessionID:    "session-1",
			Strategy:     "manual-commit",
			Subagents: map[string]SubagentInfo{
				"toolu_abc123": {
					AgentID:     "agent-session-1",
					Type:        "dev",
					Description: "Implement login feature",
				},
				"toolu_def456": {
					AgentID:     "agent-session-2",
					Type:        "reviewer",
					Description: "Review code changes",
				},
			},
		}

		data, err := json.Marshal(original)
		require.NoError(t, err)

		var restored CommittedMetadata
		err = json.Unmarshal(data, &restored)
		require.NoError(t, err)

		assert.Equal(t, original.Subagents, restored.Subagents)
		require.Len(t, restored.Subagents, 2)

		info := restored.Subagents["toolu_abc123"]
		assert.Equal(t, "agent-session-1", info.AgentID)
		assert.Equal(t, "dev", info.Type)
		assert.Equal(t, "Implement login feature", info.Description)
	})

	t.Run("partial_fields_round_trip", func(t *testing.T) {
		t.Parallel()

		original := CommittedMetadata{
			CheckpointID: "abc123def456",
			SessionID:    "session-1",
			Strategy:     "manual-commit",
			Subagents: map[string]SubagentInfo{
				"toolu_minimal": {
					AgentID: "agent-1",
					// Type and Description intentionally omitted
				},
			},
		}

		data, err := json.Marshal(original)
		require.NoError(t, err)

		var restored CommittedMetadata
		err = json.Unmarshal(data, &restored)
		require.NoError(t, err)

		info := restored.Subagents["toolu_minimal"]
		assert.Equal(t, "agent-1", info.AgentID)
		assert.Empty(t, info.Type)
		assert.Empty(t, info.Description)
	})
}

func TestCommittedMetadata_SubagentsField_OmitsWhenEmpty(t *testing.T) {
	t.Parallel()

	t.Run("nil_map_omits_field", func(t *testing.T) {
		t.Parallel()

		meta := CommittedMetadata{
			CheckpointID: "abc123def456",
			SessionID:    "session-1",
			Strategy:     "manual-commit",
			Subagents:    nil,
		}

		data, err := json.Marshal(meta)
		require.NoError(t, err)

		// The JSON should not contain "subagents" key at all
		var raw map[string]json.RawMessage
		err = json.Unmarshal(data, &raw)
		require.NoError(t, err)

		_, hasSubagents := raw["subagents"]
		assert.False(t, hasSubagents, "subagents field should be omitted when nil")
	})

	t.Run("empty_map_omits_field", func(t *testing.T) {
		t.Parallel()

		// Note: Go's omitempty treats empty maps as "empty" and omits them
		meta := CommittedMetadata{
			CheckpointID: "abc123def456",
			SessionID:    "session-1",
			Strategy:     "manual-commit",
			Subagents:    map[string]SubagentInfo{},
		}

		data, err := json.Marshal(meta)
		require.NoError(t, err)

		// With omitempty, empty maps should also be omitted
		// Note: Go's encoding/json does NOT omit empty maps with omitempty.
		// Only nil maps are omitted. Let's verify the actual behavior.
		var raw map[string]json.RawMessage
		err = json.Unmarshal(data, &raw)
		require.NoError(t, err)

		// Go's json omitempty does NOT omit empty (non-nil) maps.
		// This test documents that behavior - empty maps serialize as {}.
		// For true omission, use nil.
		_, hasSubagents := raw["subagents"]
		assert.True(t, hasSubagents, "Go omitempty does not omit empty (non-nil) maps")
	})
}

func TestSubagentInfo_JSONTags(t *testing.T) {
	t.Parallel()

	t.Run("omits_empty_optional_fields", func(t *testing.T) {
		t.Parallel()

		info := SubagentInfo{
			AgentID: "agent-1",
		}

		data, err := json.Marshal(info)
		require.NoError(t, err)

		var raw map[string]json.RawMessage
		err = json.Unmarshal(data, &raw)
		require.NoError(t, err)

		_, hasAgentID := raw["agent_id"]
		assert.True(t, hasAgentID, "agent_id should always be present")

		_, hasType := raw["type"]
		assert.False(t, hasType, "type should be omitted when empty")

		_, hasDescription := raw["description"]
		assert.False(t, hasDescription, "description should be omitted when empty")
	})
}

