func TestSaveTaskStep_AccumulatesSubagentInfo(t *testing.T) {
	dir := t.TempDir()
	repo, err := git.PlainInit(dir, false)
	if err != nil {
		t.Fatalf("failed to init git repo: %v", err)
	}

	// Create initial commit
	wt, err := repo.Worktree()
	if err != nil {
		t.Fatalf("failed to get worktree: %v", err)
	}
	testFile := filepath.Join(dir, "test.txt")
	if err := os.WriteFile(testFile, []byte("initial content"), 0o644); err != nil {
		t.Fatalf("failed to write file: %v", err)
	}
	if _, err := wt.Add("test.txt"); err != nil {
		t.Fatalf("failed to add file: %v", err)
	}
	_, err = wt.Commit("Initial commit", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	if err != nil {
		t.Fatalf("failed to commit: %v", err)
	}

	t.Chdir(dir)

	s := &ManualCommitStrategy{}
	sessionID := "2025-01-15-subagent-accumulate-test"

	// Create metadata directory with transcript
	metadataDir := ".entire/metadata/" + sessionID
	metadataDirAbs := filepath.Join(dir, metadataDir)
	if err := os.MkdirAll(metadataDirAbs, 0o755); err != nil {
		t.Fatalf("failed to create metadata dir: %v", err)
	}
	transcript := `{"type":"human","message":{"content":"test"}}` + "\n"
	if err := os.WriteFile(filepath.Join(metadataDirAbs, paths.TranscriptFileName), []byte(transcript), 0o644); err != nil {
		t.Fatalf("failed to write transcript: %v", err)
	}

	// Establish session with an initial SaveStep (creates shadow branch)
	err = s.SaveStep(context.Background(), StepContext{
		SessionID:      sessionID,
		ModifiedFiles:  []string{},
		NewFiles:       []string{},
		DeletedFiles:   []string{},
		MetadataDir:    metadataDir,
		MetadataDirAbs: metadataDirAbs,
		CommitMessage:  "Initial checkpoint",
		AuthorName:     "Test",
		AuthorEmail:    "test@test.com",
	})
	if err != nil {
		t.Fatalf("SaveStep() error = %v", err)
	}

	// Verify initial state has no subagents
	initialState, err := s.loadSessionState(context.Background(), sessionID)
	if err != nil {
		t.Fatalf("loadSessionState() error = %v", err)
	}
	if len(initialState.Subagents) != 0 {
		t.Fatalf("expected no subagents initially, got %d", len(initialState.Subagents))
	}

	// Call SaveTaskStep with a NON-incremental task step that has AgentID
	err = s.SaveTaskStep(context.Background(), TaskStepContext{
		SessionID:              sessionID,
		ToolUseID:              "toolu_final_task_1",
		AgentID:                "agent-session-abc",
		SubagentType:           "dev",
		TaskDescription:        "Implement login feature",
		ModifiedFiles:          []string{"test.txt"},
		NewFiles:               []string{},
		DeletedFiles:           []string{},
		TranscriptPath:         filepath.Join(metadataDirAbs, paths.TranscriptFileName),
		SubagentTranscriptPath: "",
		CheckpointUUID:         "uuid-final-1",
		AuthorName:             "Test",
		AuthorEmail:            "test@test.com",
		IsIncremental:          false,
	})
	if err != nil {
		t.Fatalf("SaveTaskStep() non-incremental error = %v", err)
	}

	// Verify subagent was accumulated
	state, err := s.loadSessionState(context.Background(), sessionID)
	if err != nil {
		t.Fatalf("loadSessionState() after non-incremental error = %v", err)
	}
	if len(state.Subagents) != 1 {
		t.Fatalf("expected 1 subagent, got %d", len(state.Subagents))
	}
	info, ok := state.Subagents["toolu_final_task_1"]
	if !ok {
		t.Fatal("expected subagent entry for toolu_final_task_1")
	}
	if info.AgentID != "agent-session-abc" {
		t.Errorf("AgentID = %q, want %q", info.AgentID, "agent-session-abc")
	}
	if info.Type != "dev" {
		t.Errorf("Type = %q, want %q", info.Type, "dev")
	}
	if info.Description != "Implement login feature" {
		t.Errorf("Description = %q, want %q", info.Description, "Implement login feature")
	}

	// Call SaveTaskStep with an INCREMENTAL task step - should NOT accumulate
	err = s.SaveTaskStep(context.Background(), TaskStepContext{
		SessionID:           sessionID,
		ToolUseID:           "toolu_incremental_1",
		AgentID:             "agent-session-def",
		SubagentType:        "reviewer",
		TaskDescription:     "Review code changes",
		ModifiedFiles:       []string{},
		NewFiles:            []string{},
		DeletedFiles:        []string{},
		TranscriptPath:      filepath.Join(metadataDirAbs, paths.TranscriptFileName),
		CheckpointUUID:      "uuid-inc-1",
		AuthorName:          "Test",
		AuthorEmail:         "test@test.com",
		IsIncremental:       true,
		IncrementalSequence: 1,
		IncrementalType:     "Edit",
	})
	if err != nil {
		t.Fatalf("SaveTaskStep() incremental error = %v", err)
	}

	// Verify incremental did NOT add a subagent entry
	stateAfterInc, err := s.loadSessionState(context.Background(), sessionID)
	if err != nil {
		t.Fatalf("loadSessionState() after incremental error = %v", err)
	}
	if len(stateAfterInc.Subagents) != 1 {
		t.Fatalf("expected still 1 subagent after incremental, got %d", len(stateAfterInc.Subagents))
	}
	if _, ok := stateAfterInc.Subagents["toolu_incremental_1"]; ok {
		t.Error("incremental checkpoint should NOT accumulate subagent info")
	}

	// Call SaveTaskStep with non-incremental but empty AgentID - should NOT accumulate
	err = s.SaveTaskStep(context.Background(), TaskStepContext{
		SessionID:       sessionID,
		ToolUseID:       "toolu_no_agent",
		AgentID:         "", // Empty AgentID
		SubagentType:    "dev",
		TaskDescription: "Some task",
		ModifiedFiles:   []string{},
		NewFiles:        []string{},
		DeletedFiles:    []string{},
		TranscriptPath:  filepath.Join(metadataDirAbs, paths.TranscriptFileName),
		CheckpointUUID:  "uuid-no-agent",
		AuthorName:      "Test",
		AuthorEmail:     "test@test.com",
		IsIncremental:   false,
	})
	if err != nil {
		t.Fatalf("SaveTaskStep() empty AgentID error = %v", err)
	}

	// Verify empty AgentID did NOT add a subagent entry
	stateAfterEmpty, err := s.loadSessionState(context.Background(), sessionID)
	if err != nil {
		t.Fatalf("loadSessionState() after empty AgentID error = %v", err)
	}
	if len(stateAfterEmpty.Subagents) != 1 {
		t.Fatalf("expected still 1 subagent after empty AgentID, got %d", len(stateAfterEmpty.Subagents))
	}

	// Call a second non-incremental task step with AgentID - should accumulate a second entry
	err = s.SaveTaskStep(context.Background(), TaskStepContext{
		SessionID:              sessionID,
		ToolUseID:              "toolu_final_task_2",
		AgentID:                "agent-session-xyz",
		SubagentType:           "reviewer",
		TaskDescription:        "Review pull request",
		ModifiedFiles:          []string{},
		NewFiles:               []string{},
		DeletedFiles:           []string{},
		TranscriptPath:         filepath.Join(metadataDirAbs, paths.TranscriptFileName),
		SubagentTranscriptPath: "",
		CheckpointUUID:         "uuid-final-2",
		AuthorName:             "Test",
		AuthorEmail:            "test@test.com",
		IsIncremental:          false,
	})
	if err != nil {
		t.Fatalf("SaveTaskStep() second non-incremental error = %v", err)
	}

	// Verify both subagents are accumulated
	finalState, err := s.loadSessionState(context.Background(), sessionID)
	if err != nil {
		t.Fatalf("loadSessionState() final error = %v", err)
	}
	if len(finalState.Subagents) != 2 {
		t.Fatalf("expected 2 subagents, got %d", len(finalState.Subagents))
	}

	info2, ok := finalState.Subagents["toolu_final_task_2"]
	if !ok {
		t.Fatal("expected subagent entry for toolu_final_task_2")
	}
	if info2.AgentID != "agent-session-xyz" {
		t.Errorf("AgentID = %q, want %q", info2.AgentID, "agent-session-xyz")
	}
	if info2.Type != "reviewer" {
		t.Errorf("Type = %q, want %q", info2.Type, "reviewer")
	}
	if info2.Description != "Review pull request" {
		t.Errorf("Description = %q, want %q", info2.Description, "Review pull request")
	}
}

