332→   332→// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
333→   333→// Returns the absolute file paths from the git tree root for the sessions map.
334→   334→func (s *GitStore) writeSessionToSubdirectory(ctx context.Context, opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
335→   335→	filePaths := SessionFilePaths{}
336→   336→
337→   337→	// Clear any existing entries at this path so stale files from a previous
338→   338→	// write (e.g. prompt.txt, context.md) don't persist on overwrite.
339→   339→	for key := range entries {
340→   340→		if strings.HasPrefix(key, sessionPath) {
341→   341→			delete(entries, key)
342→   342→		}
343→   343→	}
344→   344→
345→   345→	// Write transcript
346→   346→	if err := s.writeTranscript(ctx, opts, sessionPath, entries); err != nil {
347→   347→		return filePaths, err
348→   348→	}
349→   349→	filePaths.Transcript = "/" + sessionPath + paths.TranscriptFileName
350→   350→	filePaths.ContentHash = "/" + sessionPath + paths.ContentHashFileName
351→   351→
352→   352→	// Write prompts
353→   353→	if len(opts.Prompts) > 0 {
354→   354→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
355→   355→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
356→   356→		if err != nil {
357→   357→			return filePaths, err
358→   358→		}
359→   359→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
360→   360→			Name: sessionPath + paths.PromptFileName,
361→   361→			Mode: filemode.Regular,
362→   362→			Hash: blobHash,
363→   363→		}
364→   364→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
365→   365→	}
366→   366→
367→   367→	// Write context
368→   368→	if len(opts.Context) > 0 {
369→   369→		blobHash, err := CreateBlobFromContent(s.repo, redact.Bytes(opts.Context))
370→   370→		if err != nil {
371→   371→			return filePaths, err
372→   372→		}
373→   373→		entries[sessionPath+paths.ContextFileName] = object.TreeEntry{
374→   374→			Name: sessionPath + paths.ContextFileName,
375→   375→			Mode: filemode.Regular,
376→   376→			Hash: blobHash,
377→   377→		}
378→   378→		filePaths.Context = "/" + sessionPath + paths.ContextFileName
379→   379→	}
380→   380→
381→   381→	// Write session-level metadata.json (CommittedMetadata with all fields including initial_attribution)
382→   382→	sessionMetadata := CommittedMetadata{
383→   383→		CheckpointID:                opts.CheckpointID,
384→   384→		SessionID:                   opts.SessionID,
385→   385→		Strategy:                    opts.Strategy,
386→   386→		CreatedAt:                   time.Now().UTC(),
387→   387→		Branch:                      opts.Branch,
388→   388→		CheckpointsCount:            opts.CheckpointsCount,
389→   389→		FilesTouched:                opts.FilesTouched,
390→   390→		Agent:                       opts.Agent,
391→   391→		TurnID:                      opts.TurnID,
392→   392→		IsTask:                      opts.IsTask,
393→   393→		ToolUseID:                   opts.ToolUseID,
394→   394→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
395→   395→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
396→   396→		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart, // Deprecated: kept for backward compat
397→   397→		TokenUsage:                  opts.TokenUsage,
398→   398→		InitialAttribution:          opts.InitialAttribution,
399→   399→		Summary:                     redactSummary(opts.Summary),
400→   400→		CLIVersion:                  versioninfo.Version,
401→   401→	}
402→   402→
403→   403→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
404→   404→	if err != nil {
405→   405→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
406→   406→	}
407→   407→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
408→   408→	if err != nil {
409→   409→		return filePaths, err
410→   410→	}
411→   411→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
412→   412→		Name: sessionPath + paths.MetadataFileName,
413→   413→		Mode: filemode.Regular,
414→   414→		Hash: metadataHash,
415→   415→	}
416→   416→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
417→   417→
418→   418→	return filePaths, nil
419→   419→}
