421→   421→// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
422→   422→// sessions is the complete sessions array (already built by the caller).
423→   423→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths) error {
424→   424→	checkpointsCount, filesTouched, tokenUsage, err :=
425→   425→		s.reaggregateFromEntries(basePath, len(sessions), entries)
426→   426→	if err != nil {
427→   427→		return fmt.Errorf("failed to aggregate session stats: %w", err)
428→   428→	}
429→   429→
430→   430→	summary := CheckpointSummary{
431→   431→		CheckpointID:     opts.CheckpointID,
432→   432→		CLIVersion:       versioninfo.Version,
433→   433→		Strategy:         opts.Strategy,
434→   434→		Branch:           opts.Branch,
435→   435→		CheckpointsCount: checkpointsCount,
436→   436→		FilesTouched:     filesTouched,
437→   437→		Sessions:         sessions,
438→   438→		TokenUsage:       tokenUsage,
439→   439→	}
440→   440→
441→   441→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
442→   442→	if err != nil {
443→   443→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
444→   444→	}
445→   445→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
446→   446→	if err != nil {
447→   447→		return err
448→   448→	}
449→   449→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
450→   450→		Name: basePath + paths.MetadataFileName,
451→   451→		Mode: filemode.Regular,
452→   452→		Hash: metadataHash,
453→   453→	}
454→   454→	return nil
455→   455→}
