 19→// setupRepoForUpdate creates a repo with an initial commit and writes a committed checkpoint.
 20→func setupRepoForUpdate(t *testing.T) (*git.Repository, *GitStore, id.CheckpointID) {
 21→	t.Helper()
 22→
 23→	tempDir := t.TempDir()
 24→	repo, err := git.PlainInit(tempDir, false)
 25→	if err != nil {
 26→		t.Fatalf("failed to init git repo: %v", err)
 27→	}
 28→
 29→	worktree, err := repo.Worktree()
 30→	if err != nil {
 31→		t.Fatalf("failed to get worktree: %v", err)
 32→	}
 33→
 34→	readmeFile := filepath.Join(tempDir, "README.md")
 35→	if err := os.WriteFile(readmeFile, []byte("# Test"), 0o644); err != nil {
 36→		t.Fatalf("failed to write README: %v", err)
 37→	}
 38→	if _, err := worktree.Add("README.md"); err != nil {
 39→		t.Fatalf("failed to add README: %v", err)
 40→	}
 41→	if _, err := worktree.Commit("Initial commit", &git.CommitOptions{
 42→		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
 43→	}); err != nil {
 44→		t.Fatalf("failed to commit: %v", err)
 45→	}
 46→
 47→	store := NewGitStore(repo)
 48→	cpID := id.MustCheckpointID("a1b2c3d4e5f6")
 49→
 50→	err = store.WriteCommitted(context.Background(), WriteCommittedOptions{
 51→		CheckpointID: cpID,
 52→		SessionID:    "session-001",
 53→		Strategy:     "manual-commit",
 54→		Transcript:   []byte("provisional transcript line 1\n"),
 55→		Prompts:      []string{"initial prompt"},
 56→		Context:      []byte("initial context"),
 57→		AuthorName:   "Test",
 58→		AuthorEmail:  "test@test.com",
 59→	})
 60→	if err != nil {
 61→		t.Fatalf("WriteCommitted() error = %v", err)
 62→	}
 63→
 64→	return repo, store, cpID
 65→}
