425→func TestUpdateCommitted_UsesCorrectAuthor(t *testing.T) {
426→	// Cannot use t.Parallel() because subtests use t.Setenv.
427→
428→	tests := []struct {
429→		name        string
430→		localName   string
431→		localEmail  string
432→		globalName  string
433→		globalEmail string
434→		wantName    string
435→		wantEmail   string
436→	}{
437→		{
438→			name:        "global config only",
439→			globalName:  "Global User",
440→			globalEmail: "global@example.com",
441→			wantName:    "Global User",
442→			wantEmail:   "global@example.com",
443→		},
444→		{
445→			name:       "local config takes precedence",
446→			localName:  "Local User",
447→			localEmail: "local@example.com",
448→			globalName: "Global User",
449→			wantName:   "Local User",
450→			wantEmail:  "local@example.com",
451→		},
452→	}
453→
454→	for _, tt := range tests {
455→		t.Run(tt.name, func(t *testing.T) {
456→			// Isolate global git config by pointing HOME to a temp dir
457→			home := t.TempDir()
458→			t.Setenv("HOME", home)
459→			t.Setenv("XDG_CONFIG_HOME", "")
460→
461→			// Write global .gitconfig if needed
462→			if tt.globalName != "" || tt.globalEmail != "" {
463→				globalCfg := "[user]\n"
464→				if tt.globalName != "" {
465→					globalCfg += "\tname = " + tt.globalName + "\n"
466→				}
467→				if tt.globalEmail != "" {
468→					globalCfg += "\temail = " + tt.globalEmail + "\n"
469→				}
470→				if err := os.WriteFile(filepath.Join(home, ".gitconfig"), []byte(globalCfg), 0o644); err != nil {
471→					t.Fatalf("failed to write global gitconfig: %v", err)
472→				}
473→			}
474→
475→			// Create repo
476→			dir := t.TempDir()
477→			repo, err := git.PlainInit(dir, false)
478→			if err != nil {
479→				t.Fatalf("failed to init repo: %v", err)
480→			}
481→
482→			// Set local config if needed
483→			if tt.localName != "" || tt.localEmail != "" {
484→				cfg, err := repo.Config()
485→				if err != nil {
486→					t.Fatalf("failed to get repo config: %v", err)
487→				}
488→				cfg.User.Name = tt.localName
489→				cfg.User.Email = tt.localEmail
490→				if err := repo.SetConfig(cfg); err != nil {
491→					t.Fatalf("failed to set repo config: %v", err)
492→				}
493→			}
494→
495→			// Create initial commit so repo has HEAD
496→			wt, err := repo.Worktree()
497→			if err != nil {
498→				t.Fatalf("failed to get worktree: %v", err)
499→			}
500→			readmeFile := filepath.Join(dir, "README.md")
501→			if err := os.WriteFile(readmeFile, []byte("# Test"), 0o644); err != nil {
502→				t.Fatalf("failed to write README: %v", err)
503→			}
504→			if _, err := wt.Add("README.md"); err != nil {
505→				t.Fatalf("failed to add README: %v", err)
506→			}
507→			if _, err := wt.Commit("Initial commit", &git.CommitOptions{
508→				Author: &object.Signature{Name: "Setup", Email: "setup@test.com"},
509→			}); err != nil {
510→				t.Fatalf("failed to commit: %v", err)
511→			}
512→
513→			// Write initial checkpoint
514→			store := NewGitStore(repo)
515→			cpID := id.MustCheckpointID("a1b2c3d4e5f6")
516→			err = store.WriteCommitted(context.Background(), WriteCommittedOptions{
517→				CheckpointID: cpID,
518→				SessionID:    "session-001",
519→				Strategy:     "manual-commit",
520→				Transcript:   []byte("provisional\n"),
521→				AuthorName:   tt.wantName,
522→				AuthorEmail:  tt.wantEmail,
523→			})
524→			if err != nil {
525→				t.Fatalf("WriteCommitted() error = %v", err)
526→			}
527→
528→			// Call UpdateCommitted — this is the operation under test
529→			err = store.UpdateCommitted(context.Background(), UpdateCommittedOptions{
530→				CheckpointID: cpID,
531→				SessionID:    "session-001",
532→				Transcript:   []byte("full transcript\n"),
533→			})
534→			if err != nil {
535→				t.Fatalf("UpdateCommitted() error = %v", err)
536→			}
537→
538→			// Read the latest commit on entire/checkpoints/v1 and verify author
539→			ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
540→			if err != nil {
541→				t.Fatalf("failed to get sessions branch ref: %v", err)
542→			}
543→			commit, err := repo.CommitObject(ref.Hash())
544→			if err != nil {
545→				t.Fatalf("failed to get commit: %v", err)
546→			}
547→
548→			if commit.Author.Name != tt.wantName {
549→				t.Errorf("commit author name = %q, want %q", commit.Author.Name, tt.wantName)
550→			}
551→			if commit.Author.Email != tt.wantEmail {
552→				t.Errorf("commit author email = %q, want %q", commit.Author.Email, tt.wantEmail)
553→			}
554→		})
555→	}
556→}
