func TestExtractSubagentBlobs_CollectsAgentTranscripts(t *testing.T) {
	s, sessionID, transcriptPath := setupTaskStepTestEnv(t)

	// Create a subagent transcript file
	subagentDir := filepath.Dir(transcriptPath)
	subagentTranscript := filepath.Join(subagentDir, "subagent-transcript.jsonl")
	if err := os.WriteFile(subagentTranscript, []byte(`{"type":"assistant","message":"subagent output"}`+"\n"), 0o644); err != nil {
		t.Fatalf("failed to write subagent transcript: %v", err)
	}

	// SaveTaskStep with a subagent transcript to populate the shadow branch
	err := s.SaveTaskStep(context.Background(), TaskStepContext{
		SessionID:              sessionID,
		ToolUseID:              "toolu_extract_01",
		AgentID:                "agent-sub-abc",
		SubagentType:           "dev",
		TaskDescription:        "Implement feature",
		ModifiedFiles:          []string{"test.txt"},
		NewFiles:               []string{},
		DeletedFiles:           []string{},
		TranscriptPath:         transcriptPath,
		SubagentTranscriptPath: subagentTranscript,
		CheckpointUUID:         "uuid-extract-1",
		AuthorName:             "Test",
		AuthorEmail:            "test@test.com",
		IsIncremental:          false,
	})
	if err != nil {
		t.Fatalf("SaveTaskStep() error = %v", err)
	}

	// Load state to get base commit and worktree ID
	state, err := s.loadSessionState(context.Background(), sessionID)
	if err != nil {
		t.Fatalf("loadSessionState() error = %v", err)
	}

	// Resolve shadow branch ref
	repo, err := OpenRepository(context.Background())
	if err != nil {
		t.Fatalf("OpenRepository() error = %v", err)
	}
	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	ref, err := repo.Reference(plumbing.NewBranchReferenceName(shadowBranchName), true)
	if err != nil {
		t.Fatalf("failed to resolve shadow branch: %v", err)
	}

	// Call extractSubagentBlobs
	blobs, err := extractSubagentBlobs(repo, ref.Hash(), sessionID)
	if err != nil {
		t.Fatalf("extractSubagentBlobs() error = %v", err)
	}

	if len(blobs) != 1 {
		t.Fatalf("expected 1 blob, got %d", len(blobs))
	}

	expectedPath := "subagents/toolu_extract_01/agent-agent-sub-abc.jsonl"
	entry, ok := blobs[expectedPath]
	if !ok {
		t.Fatalf("expected blob at %q, got keys: %v", expectedPath, blobKeys(blobs))
	}
	if entry.Hash.IsZero() {
		t.Error("blob hash should not be zero")
	}
}

func TestExtractSubagentBlobs_NoTasksReturnsNil(t *testing.T) {
	dir := t.TempDir()
	repo, err := git.PlainInit(dir, false)
	if err != nil {
		t.Fatalf("failed to init repo: %v", err)
	}
	wt, err := repo.Worktree()
	if err != nil {
		t.Fatalf("failed to get worktree: %v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, "test.txt"), []byte("initial"), 0o644); err != nil {
		t.Fatalf("failed to write file: %v", err)
	}
	if _, err := wt.Add("test.txt"); err != nil {
		t.Fatalf("failed to add file: %v", err)
	}
	commitHash, err := wt.Commit("Initial commit", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	if err != nil {
		t.Fatalf("failed to commit: %v", err)
	}

	// No tasks exist on this commit tree
	blobs, err := extractSubagentBlobs(repo, commitHash, "2025-01-15-no-tasks")
	if err != nil {
		t.Fatalf("extractSubagentBlobs() error = %v", err)
	}
	if blobs != nil {
		t.Errorf("expected nil blobs when no tasks directory exists, got %v", blobs)
	}
}

