func TestCondenseSession_PreservesSubagentTranscripts(t *testing.T) {
	s, sessionID, transcriptPath := setupTaskStepTestEnv(t)

	// Create subagent transcript file
	subagentDir := filepath.Dir(transcriptPath)
	subagentTranscript := filepath.Join(subagentDir, "subagent-transcript.jsonl")
	subagentContent := `{"type":"assistant","message":"subagent did work"}` + "\n"
	if err := os.WriteFile(subagentTranscript, []byte(subagentContent), 0o644); err != nil {
		t.Fatalf("failed to write subagent transcript: %v", err)
	}

	// SaveTaskStep to create the subagent transcript on the shadow branch
	err := s.SaveTaskStep(context.Background(), TaskStepContext{
		SessionID:              sessionID,
		ToolUseID:              "toolu_condense_01",
		AgentID:                "agent-condense-abc",
		SubagentType:           "dev",
		TaskDescription:        "Implement condensation feature",
		ModifiedFiles:          []string{"test.txt"},
		NewFiles:               []string{},
		DeletedFiles:           []string{},
		TranscriptPath:         transcriptPath,
		SubagentTranscriptPath: subagentTranscript,
		CheckpointUUID:         "uuid-condense-1",
		AuthorName:             "Test",
		AuthorEmail:            "test@test.com",
		IsIncremental:          false,
	})
	if err != nil {
		t.Fatalf("SaveTaskStep() error = %v", err)
	}

	// Load session state (updated by SaveTaskStep with subagent info)
	state, err := s.loadSessionState(context.Background(), sessionID)
	if err != nil {
		t.Fatalf("loadSessionState() error = %v", err)
	}

	// Verify subagent info is in state before condensation
	if len(state.Subagents) != 1 {
		t.Fatalf("expected 1 subagent in state, got %d", len(state.Subagents))
	}

	repo, err := OpenRepository(context.Background())
	if err != nil {
		t.Fatalf("OpenRepository() error = %v", err)
	}

	// Condense the session
	checkpointID := id.MustCheckpointID("c0de5abagent")
	result, err := s.CondenseSession(context.Background(), repo, checkpointID, state, nil)
	if err != nil {
		t.Fatalf("CondenseSession() error = %v", err)
	}
	if result.CheckpointID != checkpointID {
		t.Errorf("CheckpointID = %s, want %s", result.CheckpointID, checkpointID)
	}

	// Verify subagent transcript exists on the committed branch
	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		t.Fatalf("failed to get sessions branch: %v", err)
	}
	sessionsCommit, err := repo.CommitObject(sessionsRef.Hash())
	if err != nil {
		t.Fatalf("failed to get sessions commit: %v", err)
	}
	sessionsTree, err := sessionsCommit.Tree()
	if err != nil {
		t.Fatalf("failed to get sessions tree: %v", err)
	}

	// The subagent transcript should be at <checkpoint-path>/0/subagents/<tool-use-id>/agent-<id>.jsonl
	subagentPath := checkpointID.Path() + "/0/subagents/toolu_condense_01/agent-agent-condense-abc.jsonl"
	file, err := sessionsTree.File(subagentPath)
	if err != nil {
		t.Fatalf("subagent transcript not found at %q: %v", subagentPath, err)
	}

	content, err := file.Contents()
	if err != nil {
		t.Fatalf("failed to read subagent transcript content: %v", err)
	}
	if content == "" {
		t.Error("subagent transcript content should not be empty")
	}

	// Verify session metadata contains subagents field
	store := checkpoint.NewGitStore(repo)
	sessionContent, err := store.ReadLatestSessionContent(t.Context(), checkpointID)
	if err != nil {
		t.Fatalf("ReadLatestSessionContent() error = %v", err)
	}
	if len(sessionContent.Metadata.Subagents) != 1 {
		t.Fatalf("expected 1 subagent in metadata, got %d", len(sessionContent.Metadata.Subagents))
	}
	info := sessionContent.Metadata.Subagents["toolu_condense_01"]
	if info.AgentID != "agent-condense-abc" {
		t.Errorf("Subagent AgentID = %q, want %q", info.AgentID, "agent-condense-abc")
	}
	if info.Type != "dev" {
		t.Errorf("Subagent Type = %q, want %q", info.Type, "dev")
	}
	if info.Description != "Implement condensation feature" {
		t.Errorf("Subagent Description = %q, want %q", info.Description, "Implement condensation feature")
